--   ALTER TABLE public.profiles DROP COLUMN IF EXISTS onboarding_persona;
--   DROP INDEX IF EXISTS idx_profiles_onboarding_persona;
--   DROP TYPE IF EXISTS public.onboarding_persona;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname = 'onboarding_persona'
      AND typnamespace = 'public'::regnamespace
  ) THEN
    CREATE TYPE public.onboarding_persona AS ENUM ('solo_artist', 'studio_owner');
  END IF;
END
$$;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS onboarding_persona public.onboarding_persona NOT NULL DEFAULT 'studio_owner';

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS onboarded_at timestamptz;

CREATE INDEX IF NOT EXISTS idx_profiles_onboarding_persona
  ON public.profiles (onboarding_persona);

